import java.awt.image.BufferedImage; import java.io.File; import javax.imageio.ImageIO;
public class Col { public static void main(String[] a) throws Exception { int sep = java.util.Arrays.asList(a).indexOf("--"); int x = Integer.parseInt(a[sep+1]), y0 = Integer.parseInt(a[sep+2]), y1 = Integer.parseInt(a[sep+3]); BufferedImage[] im = new BufferedImage[sep]; for (int i = 0; i < sep; i++) im[i] = ImageIO.read(new File(a[i])); for (int y = y0; y <= y1; y++) { StringBuilder sb = new StringBuilder(String.format("%4d ", y)); for (BufferedImage b : im) sb.append(String.format(" %06x", b.getRGB(x, y) & 0xffffff)); System.out.println(sb); } } }
